<?php
declare(strict_types=1);
require_once ROOT.'/app/Core/RecordWorkspace.php';
final class EmployeeService extends RecordWorkspace {
    protected const TABLE='employee_records';
    public static function save(string $kind,array $input,?int $id=null,bool $transaction=true):int{return $transaction?Db::tx(fn()=>parent::save($kind,$input,$id)):parent::save($kind,$input,$id);}
    public static function archive(string $kind,int $id):void{if($kind==='invoice_lines'){$d=self::get($id,$kind)['fields'];if(self::get($d['invoice'],'invoices')['fields']['state']!=='draft')throw new InvalidArgumentException(t('Issued invoice items cannot be removed.'));}parent::archive($kind,$id);}
    public static function catalog():array{return [
        'attendance'=>['Timesheet & overtime',['date'=>'date','start'=>'time','end'=>'time','break_minutes'=>'int:0:720','regular_minutes'=>'int:1:1440','hourly_rate'=>'money0','overtime_multiplier'=>'decimal','notes'=>'?text']],
        'leave_policies'=>['Leave balances',['type'=>'enum:annual,casual,medical,other','year'=>'int:2000:2100','opening_days'=>'decimal','accrued_days'=>'decimal','carry_over_days'=>'decimal']],
        'leave'=>['Leave planner',['policy'=>'ref:leave_policies','starts'=>'date','ends'=>'date','days'=>'decimal','state'=>'enum:requested,approved,rejected,cancelled','notes'=>'?text']],
        'payslips'=>['Payslips & take-home',['month'=>'month','gross'=>'money','epf_rate'=>'decimal','etf_rate'=>'decimal','apit'=>'money0','other_deductions'=>'money0','effective_date'=>'date','source'=>'text']],
        'meetings'=>['Meeting notes',['title'=>'text','date'=>'date','notes'=>'text']],
        'actions'=>['Meeting actions',['meeting'=>'ref:meetings','title'=>'text','due'=>'date']],
        'blockers'=>['Stand-up blockers',['title'=>'text','date'=>'date','state'=>'enum:open,resolved','notes'=>'?text']],
        'achievements'=>['Achievements / brag document',['title'=>'text','date'=>'date','outcome'=>'text','evidence'=>'?url']],
        'objectives'=>['KPI / OKR',['title'=>'text','period_start'=>'date','period_end'=>'date','baseline'=>'decimal','target'=>'decimal','current'=>'decimal','direction'=>'enum:increase,decrease','unit'=>'text']],
        'claims'=>['Claims & reimbursements',['title'=>'text','date'=>'date','kind'=>'enum:travel,meal,other','amount'=>'money','state'=>'enum:draft,submitted,approved,paid,rejected','reimbursed'=>'money0','evidence'=>'?url']],
        'worklife'=>['Work-life alert policies',['title'=>'text','threshold_hours'=>'decimal','consecutive_days'=>'int:1:14']],
        'offers'=>['Job-offer comparison',['company'=>'text','role'=>'text','monthly_net'=>'money','monthly_commute'=>'money0','weekly_hours'=>'decimal','benefits'=>'?text','notice_days'=>'int:0:365','probation_ends'=>'?date']],
        'promotion'=>['Promotion & skill gaps',['title'=>'text','criteria'=>'text','current_skills'=>'text','needed_skills'=>'text','course'=>'?text','due'=>'date','state'=>'enum:planned,learning,evidenced,complete']],
        'clients'=>['Invoice clients',['name'=>'text','email'=>'?text','address'=>'?text']],
        'invoices'=>['Side-income invoices',['client'=>'ref:clients','issued'=>'date','due'=>'date','currency'=>'enum:LKR,USD,EUR,GBP','state'=>'enum:draft,sent,paid,cancelled','paid'=>'money0','notes'=>'?text']],
        'invoice_lines'=>['Invoice items',['invoice'=>'ref:invoices','description'=>'text','quantity'=>'decimal','unit_price'=>'money0']],
        'credentials'=>['Certifications & licences',['title'=>'text','issuer'=>'text','issued'=>'date','expires'=>'date','remind_days'=>'int:0:365','evidence'=>'?url']],
    ];}
    protected static function validate(string $kind,array $d,?int $id):array{
        EmployeeMoney::assertEditable($kind,$d,$id);
        if($kind==='invoices'&&$id===null&&($d['state']!=='draft'||$d['paid']!=0))throw new InvalidArgumentException(t('New invoices start as unpaid drafts. Add items before sending.'));
        if($kind==='objectives'&&(($d['direction']==='increase'&&$d['target']<=$d['baseline'])||($d['direction']==='decrease'&&$d['target']>=$d['baseline'])))throw new InvalidArgumentException(t('Target must follow the selected direction from baseline.'));
        foreach([['starts','ends'],['issued','due'],['issued','expires'],['period_start','period_end']]as [$a,$b])if(isset($d[$a],$d[$b]))self::dateRange($d[$a],$d[$b]);
        if($kind==='attendance'){if($d['end']<=$d['start'])throw new InvalidArgumentException(t('Use a same-day shift with end after start. Split overnight shifts at midnight.'));$span=(strtotime($d['end'])-strtotime($d['start']))/60;if($d['break_minutes']>=$span)throw new InvalidArgumentException(t('Break must be shorter than the shift.'));foreach(self::rows($kind)as $r)if($r['id']!==$id&&$r['fields']['date']===$d['date']&&max($r['fields']['start'],$d['start'])<min($r['fields']['end'],$d['end']))throw new InvalidArgumentException(t('This shift overlaps an existing shift.'));}
        if($kind==='payslips'){if($d['epf_rate']>100||$d['etf_rate']>100)throw new InvalidArgumentException(t('Contribution rates must be between zero and 100.'));$net=self::payslip($d)['net'];if($net<0)throw new InvalidArgumentException(t('Deductions exceed gross salary.'));}
        if($kind==='claims'&&$d['reimbursed']>$d['amount'])throw new InvalidArgumentException(t('Reimbursement exceeds the claim amount.'));
        if($kind==='leave'){$p=self::get($d['policy'],'leave_policies')['fields'];if((int)substr($d['starts'],0,4)!==$p['year']||(int)substr($d['ends'],0,4)!==$p['year'])throw new InvalidArgumentException(t('Leave dates must be within the policy year.'));if($d['days']<=0)throw new InvalidArgumentException(t('Enter positive leave days.'));$used=0;foreach(self::rows('leave')as $r)if($r['id']!==$id&&$r['fields']['policy']===$d['policy']&&$r['fields']['state']==='approved')$used+=$r['fields']['days'];if($d['state']==='approved'&&$used+$d['days']>$p['opening_days']+$p['accrued_days']+$p['carry_over_days'])throw new InvalidArgumentException(t('Approved leave would exceed the available balance.'));}
        if($kind==='invoice_lines'){if($d['quantity']<=0)throw new InvalidArgumentException(t('Quantity must be positive.'));$invoice=self::get($d['invoice'],'invoices');if($invoice['fields']['state']!=='draft')throw new InvalidArgumentException(t('Only draft invoices can have line edits.'));if($id!==null&&self::get($id,$kind)['fields']['invoice']!==$d['invoice'])throw new InvalidArgumentException(t('An invoice line cannot move to another invoice.'));}
        if($kind==='invoices'&&$id!==null){$old=self::get($id,'invoices')['fields'];$total=self::invoiceTotal($id);if($d['paid']>$total||($d['state']==='paid'&&abs($d['paid']-$total)>0.005))throw new InvalidArgumentException(t('Paid amount must match the invoice total when marked paid.'));if($old['state']!=='draft'&&array_intersect_key($d,array_flip(['client','issued','currency']))!==array_intersect_key($old,array_flip(['client','issued','currency'])))throw new InvalidArgumentException(t('Issued invoice identity cannot change.'));}
        return $d;
    }
    public static function shift(array $d):array{$minutes=(int)((strtotime($d['end'])-strtotime($d['start']))/60)-$d['break_minutes'];$ot=max(0,$minutes-$d['regular_minutes']);return ['minutes'=>$minutes,'overtime'=>$ot,'pay'=>round((($minutes-$ot)+$ot*$d['overtime_multiplier'])*$d['hourly_rate']/60,2)];}
    public static function payslip(array $d):array{$epf=round($d['gross']*$d['epf_rate']/100,2);$etf=round($d['gross']*$d['etf_rate']/100,2);return ['epf'=>$epf,'employer_etf'=>$etf,'net'=>round($d['gross']-$epf-$d['apit']-$d['other_deductions'],2)];}
    public static function invoiceTotal(int $id):float{$cents=0;foreach(self::rows('invoice_lines')as $r)if($r['fields']['invoice']===$id)$cents+=(int)round($r['fields']['quantity']*cents((string)$r['fields']['unit_price'],true));return $cents/100;}
    public static function invoiceNumber(int $id):string{self::get($id,'invoices');$r=Db::one('SELECT number FROM employee_invoice_numbers WHERE record_id=?',[$id]);if($r)return $r['number'];$number='INV-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);Db::run('INSERT INTO employee_invoice_numbers(record_id,number) VALUES(?,?)',[$id,$number]);return $number;}
    public static function alerts():array{$out=[];$today=date('Y-m-d');foreach(self::rows('credentials')as $row){$d=$row['fields'];if(date('Y-m-d',strtotime($d['expires'].' -'.$d['remind_days'].' days'))<=$today)$out[]=['id'=>hash('sha256','credential:'.$row['id'].':'.$today),'title'=>t('Credential renewal'),'body'=>$d['title'].' · '.$d['expires'],'route'=>'/employee?page=credentials','level'=>$d['expires']<$today?'overdue':'upcoming'];}foreach(self::rows('worklife')as $policy){$d=$policy['fields'];$met=true;for($i=0;$i<$d['consecutive_days'];$i++){$date=date('Y-m-d',strtotime('-'.$i.' days'));$minutes=0;foreach(self::rows('attendance')as $shift)if($shift['fields']['date']===$date)$minutes+=self::shift($shift['fields'])['minutes'];if($minutes<=$d['threshold_hours']*60)$met=false;}if($met)$out[]=['id'=>hash('sha256','worklife:'.$policy['id'].':'.$today),'title'=>t('Time to review your workload'),'body'=>$d['title'],'route'=>'/employee?page=worklife','level'=>'warning'];}return $out;}
}
